// SCIM bearer-token gate. An IdP (Okta/Entra/etc.) authenticates to the SCIM endpoints with a
// static bearer token provisioned out-of-band. Set OFFGRID_SCIM_TOKEN to enable; when unset the
// endpoints are disabled (return false) so the stub can't be hit unauthenticated.
export function scimAuthorized(req: Request): boolean {
  const expected = process.env.OFFGRID_SCIM_TOKEN;
  if (!expected) return false;
  const header = req.headers.get('authorization') ?? '';
  const token = header.replace(/^Bearer\s+/i, '');
  return Boolean(token) && token === expected;
}

export const SCIM_CONTENT = 'application/scim+json';

import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  actionsFor,
  canCancel,
  canDelete,
  canRerun,
  canReview,
  isActionAllowed,
} from '../src/lib/agent-run-actions.ts';

// Unit tests for the PURE run-action state machine — no db, no mocks. Status in, valid actions out.

test('canCancel / canReview: only pending_review is in-flight', () => {
  assert.equal(canCancel('pending_review'), true);
  assert.equal(canReview('pending_review'), true);
  for (const s of ['done', 'denied', 'blocked', 'rejected', 'cancelled']) {
    assert.equal(canCancel(s), false, `${s} must not be cancellable`);
    assert.equal(canReview(s), false, `${s} must not be reviewable`);
  }
});

test('canDelete / canRerun: always allowed regardless of status', () => {
  for (const s of ['done', 'denied', 'blocked', 'pending_review', 'rejected', 'cancelled', 'weird']) {
    assert.equal(canDelete(s), true);
    assert.equal(canRerun(s), true);
  }
});

test('actionsFor: pending_review exposes review + cancel + rerun + delete', () => {
  assert.deepEqual(actionsFor('pending_review'), ['rerun', 'review', 'cancel', 'delete']);
});

test('actionsFor: terminal states expose only rerun + delete', () => {
  for (const s of ['done', 'denied', 'blocked', 'rejected', 'cancelled']) {
    assert.deepEqual(actionsFor(s), ['rerun', 'delete'], `actions for ${s}`);
  }
});

test('isActionAllowed: matches the per-action predicates', () => {
  assert.equal(isActionAllowed('cancel', 'pending_review'), true);
  assert.equal(isActionAllowed('cancel', 'done'), false);
  assert.equal(isActionAllowed('review', 'pending_review'), true);
  assert.equal(isActionAllowed('review', 'cancelled'), false);
  assert.equal(isActionAllowed('delete', 'done'), true);
  assert.equal(isActionAllowed('rerun', 'blocked'), true);
  // Unknown action is never allowed.
  assert.equal(isActionAllowed('nope' as never, 'done'), false);
});

// Every read of the search index must go through `opensearchFetch`, which is the one place auth
// headers are added.
//
// Six call sites did not. Each built its own URL from `OFFGRID_OPENSEARCH_URL` and called bare
// `fetch`, so the moment the index required authentication they all got 401 — and each degraded
// quietly in its own way rather than erroring:
//
//   • /insights/siem, /governance/evidence/security   → rendered the literal string "OpenSearch 401"
//   • /insights/usage/traffic                          → "OpenSearch is unreachable"
//   • gateway finops, token budgets, prompt observability → silently empty
//
// It stayed hidden because every OTHER read went through the helper and worked, so the service
// looked healthy from every angle we normally check. Probing OpenSearch from the box with the
// console's own credentials returns 200 for the identical query. It was only visible by rendering
// the page as a signed-in demo viewer.
//
// This is a source-shape guard, not a behavioural test, because the failure is architectural: the
// bug is "did not use the seam", and no amount of exercising the seam can detect a caller that
// bypassed it.

import assert from 'node:assert/strict';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'src');

/** The helper itself is the one file allowed to build a URL and call fetch. */
const ALLOWED = new Set([path.join(ROOT, 'lib', 'opensearch-http.ts')]);

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (/\.tsx?$/.test(full)) out.push(full);
  }
  return out;
}

/** `fetch(...)` whose URL is built from an OpenSearch base — the exact shape that shipped. */
const RAW_OPENSEARCH_FETCH =
  /await\s+fetch\(\s*`\$\{\s*OS_URL\s*\}|await\s+fetch\(\s*`\$\{[^}]*OPENSEARCH[^}]*\}/;

test('no module reads the search index with an unauthenticated fetch', () => {
  const offenders: string[] = [];
  for (const file of walk(ROOT)) {
    if (ALLOWED.has(file)) continue;
    const src = readFileSync(file, 'utf8');
    if (RAW_OPENSEARCH_FETCH.test(src)) offenders.push(path.relative(ROOT, file));
  }
  assert.deepEqual(
    offenders,
    [],
    `these bypass opensearchFetch and will 401 once the index requires auth:\n  ${offenders.join('\n  ')}`,
  );
});

test('the guard catches the exact shape that shipped', () => {
  // A guard that can only pass is not a guard. This is the line from the gateway analytics route.
  const shipped = 'const r = await fetch(`${OS_URL}/${OS_INDEX}/_search`, {';
  assert.ok(RAW_OPENSEARCH_FETCH.test(shipped), 'must match the real defect');
  // ...and does not fire on the correct form.
  assert.ok(!RAW_OPENSEARCH_FETCH.test('const r = await opensearchFetch(`/${OS_INDEX}/_search`, {'));
});

test('a module that merely NAMES the env var is not an offender', () => {
  // config-registry and services-directory legitimately reference the variable to describe or probe
  // the service. Flagging those would make the guard noisy enough to be switched off.
  assert.ok(!RAW_OPENSEARCH_FETCH.test("key: 'OFFGRID_OPENSEARCH_URL',"));
  assert.ok(!RAW_OPENSEARCH_FETCH.test("url: process.env.OFFGRID_OPENSEARCH_URL ?? 'http://127.0.0.1:9200',"));
});

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { test } from 'node:test';

import { executeCrmAction, type ActionExecutionContext } from '@/lib/adapters/action-crm';
import { CRM_TASK_API_VERSION } from '@/lib/adapters/crm-task-writeback';
import { getSigning } from '@/lib/adapters/registry';
import type { ActionStepShape } from '@/lib/action-contract';
// @ts-expect-error shared JS reachability helper
import { dbReachable, SKIP_MESSAGE } from './support/db-available.mjs';

// executeCrmAction's connector is passed in literally below (no store lookup), but for any test
// that reaches the CRM adapter's execRestConnectorRequest, resolveConnectorTarget still resolves
// a per-connector secret via connector-secrets.ts -> drizzle -> Postgres, even for a connector
// with no stored secret (a missing row is a clean null; an UNREACHABLE db surfaces as "connector
// is not a reachable REST source" — see crm-writeback.test.ts for the full trace). Only the three
// tests below that actually reach the boundary need the guard; the maker-checker/validation tests
// return before any I/O and never touch Postgres.
const dbUp = await dbReachable();

const CONTEXT: ActionExecutionContext = {
  orgId: 'org_bharat',
  runId: 'apprun_cross_sell_101',
  stepId: 'create-follow-up',
  approval: {
    stepId: 'rm-review',
    evidence: 'approved by reviewer — note: eligible offer confirmed',
  },
  now: () => new Date('2026-07-22T12:00:00.000Z'),
};

const CREATE: ActionStepShape = {
  id: 'create-follow-up',
  kind: 'action',
  actionId: 'crm.create-task',
  connectorId: 'crm_bharat',
  approvalStepId: 'rm-review',
  command: {
    operation: 'create-task',
    subject: 'Discuss the approved next-best offer',
    useCase: 'bank-cross-sell',
    kind: 'call',
    opportunityId: 'opp_101',
    dueAt: '2026-07-23T09:00:00.000Z',
    assignee: 'relationship-manager@example.test',
  },
};

function readJson(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
    req.on('end', () => {
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}'));
      } catch (error) {
        reject(error);
      }
    });
    req.on('error', reject);
  });
}

function json(
  res: ServerResponse,
  status: number,
  body: unknown,
  headers: Record<string, string> = {},
): void {
  res.writeHead(status, { 'content-type': 'application/json', ...headers });
  res.end(JSON.stringify(body));
}

test('maker-checker blocks the CRM boundary before any side effect', async () => {
  let requests = 0;
  const server = createServer((_req, res) => {
    requests += 1;
    json(res, 500, {});
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const address = server.address();
  assert.ok(address && typeof address === 'object');
  try {
    const connector = {
      id: 'crm_bharat',
      type: 'rest',
      endpoint: `http://127.0.0.1:${address.port}`,
    };
    const absent = await executeCrmAction(connector, CREATE, { ...CONTEXT, approval: undefined });
    assert.equal(absent.ok, false);
    if (!absent.ok) assert.equal(absent.code, 'approval-required');

    const wrongStep = await executeCrmAction(connector, CREATE, {
      ...CONTEXT,
      approval: { stepId: 'other-review', evidence: 'approved by reviewer' },
    });
    assert.equal(wrongStep.ok, false);
    if (!wrongStep.ok) assert.equal(wrongStep.code, 'approval-required');

    const rejected = await executeCrmAction(connector, CREATE, {
      ...CONTEXT,
      approval: { stepId: 'rm-review', evidence: 'rejected by reviewer' },
    });
    assert.equal(rejected.ok, false);
    assert.equal(requests, 0);
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
});

test(
  'generic action creates and replays a tenant-scoped CRM task through real HTTP',
  { skip: dbUp ? false : SKIP_MESSAGE },
  async (t) => {
  const ledger = new Map<string, { hash: string; task: Record<string, unknown> }>();
  const seenOrgs: string[] = [];
  const seenPaths: string[] = [];
  let writes = 0;
  const server = createServer(async (req, res) => {
    seenPaths.push(String(req.url));
    const org = String(req.headers['x-offgrid-org-id'] ?? '');
    seenOrgs.push(org);
    const body = await readJson(req);
    const key = `${org}:${String(body.idempotencyKey)}`;
    const hash = createHash('sha256').update(JSON.stringify(body)).digest('hex');
    const prior = ledger.get(key);
    const headers = { 'x-offgrid-crm-api-version': CRM_TASK_API_VERSION };
    if (prior) {
      if (prior.hash !== hash) return json(res, 409, { error: 'conflict' }, headers);
      return json(
        res,
        200,
        { apiVersion: CRM_TASK_API_VERSION, task: prior.task, replayed: true },
        { ...headers, 'x-idempotent-replay': 'true' },
      );
    }
    writes += 1;
    const task = { id: 'task_0123456789abcdef', orgId: org, ...body };
    ledger.set(key, { hash, task });
    return json(res, 201, { apiVersion: CRM_TASK_API_VERSION, task, replayed: false }, headers);
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise<void>((resolve) => server.close(() => resolve())));
  const address = server.address();
  assert.ok(address && typeof address === 'object');
  const connector = {
    id: 'crm_bharat',
    type: 'rest',
    endpoint: `http://127.0.0.1:${address.port}/db`,
  };

  const created = await executeCrmAction(connector, CREATE, CONTEXT);
  assert.equal(created.ok, true);
  if (!created.ok) return;
  assert.equal(created.receipt.status, 'executed');
  assert.equal(created.receipt.orgId, 'org_bharat');
  assert.equal(created.receipt.target, 'opp_101');
  assert.deepEqual(created.receipt.approval, CONTEXT.approval);
  assert.equal(created.impact.egress.dataLeavesOrganisation, false);
  assert.equal(created.resource.orgId, 'org_bharat');
  const provider = created.receipt.providerReceipt;
  const { signature, algorithm: _algorithm, publicKey: _publicKey, ...signed } = provider;
  assert.equal(getSigning().verify(signed, String(signature)), true);

  const replay = await executeCrmAction(connector, CREATE, CONTEXT);
  assert.equal(replay.ok, true);
  if (replay.ok) assert.equal(replay.receipt.status, 'replayed');
  assert.equal(writes, 1);
  assert.deepEqual(seenOrgs, ['org_bharat', 'org_bharat']);

  const independent = await executeCrmAction(connector, CREATE, {
    ...CONTEXT,
    runId: 'apprun_cross_sell_102',
  });
  assert.equal(independent.ok, true);
  if (independent.ok) {
    assert.equal(independent.receipt.status, 'executed');
    assert.notEqual(independent.receipt.idempotencyKey, created.receipt.idempotencyKey);
  }
  assert.equal(writes, 2, 'a different run owns an independent action');

  const conflict = await executeCrmAction(
    connector,
    { ...CREATE, command: { ...CREATE.command, subject: 'Different command' } },
    CONTEXT,
  );
  assert.equal(conflict.ok, false);
  if (!conflict.ok) assert.equal(conflict.code, 'idempotency-conflict');
  assert.equal(writes, 2);
  assert.deepEqual(
    seenPaths,
    ['/v1/tasks', '/v1/tasks', '/v1/tasks', '/v1/tasks'],
    'the legacy /db read suffix is removed without changing the CRM origin',
  );
  },
);

test(
  'generic action updates a CRM opportunity through its existing signed adapter',
  { skip: dbUp ? false : SKIP_MESSAGE },
  async (t) => {
  let record: Record<string, unknown> = { id: 'opp_202', stage: 'qualification' };
  const seenMethods: string[] = [];
  const server = createServer(async (req, res) => {
    seenMethods.push(String(req.method));
    if (req.method === 'GET') return json(res, 200, record);
    const patch = await readJson(req);
    record = { ...record, ...patch };
    return json(res, 200, record);
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise<void>((resolve) => server.close(() => resolve())));
  const address = server.address();
  assert.ok(address && typeof address === 'object');
  const step: ActionStepShape = {
    id: 'update-opportunity',
    kind: 'action',
    actionId: 'crm.update-opportunity',
    connectorId: 'crm_bharat',
    approvalStepId: 'rm-review',
    command: {
      opportunityId: 'opp_202',
      useCase: 'bank-cross-sell',
      followUp: { kind: 'meeting', summary: 'Present approved offer' },
      stage: 'proposal',
    },
  };
  const result = await executeCrmAction(
    { id: 'crm_bharat', type: 'rest', endpoint: `http://127.0.0.1:${address.port}` },
    step,
    { ...CONTEXT, stepId: step.id },
  );
  assert.equal(result.ok, true);
  if (result.ok) {
    assert.equal(result.resource.stage, 'proposal');
    assert.equal(result.receipt.target, 'opp_202');
  }
  assert.deepEqual(seenMethods, ['GET', 'PATCH']);
  },
);

test('action errors remain bounded and unsupported catalogue entries do not fabricate impact', async () => {
  const connector = { id: 'crm', type: 'rest', endpoint: 'http://127.0.0.1:1' };
  const invalid = await executeCrmAction(connector, { ...CREATE, command: {} }, CONTEXT);
  assert.equal(invalid.ok, false);
  if (!invalid.ok) assert.equal(invalid.code, 'invalid-command');

  const unsupported = await executeCrmAction(
    connector,
    { ...CREATE, actionId: 'http.request' as never },
    CONTEXT,
  );
  assert.deepEqual(unsupported, {
    ok: false,
    code: 'unsupported-action',
    message: 'This action is not available in the governed catalogue.',
  });

  const unavailable = await executeCrmAction(connector, CREATE, CONTEXT);
  assert.equal(unavailable.ok, false);
  if (!unavailable.ok) {
    assert.equal(unavailable.code, 'unsupported-connector');
    assert.equal(unavailable.message.length < 200, true);
  }
});

test('public or ambiguous CRM endpoints are blocked before any action I/O', async () => {
  const result = await executeCrmAction(
    { id: 'crm_cloud', type: 'rest', endpoint: 'https://api.example.com' },
    CREATE,
    CONTEXT,
  );
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.equal(result.code, 'unsupported-connector');
    assert.equal(
      result.message,
      'This action requires an on-prem CRM connection; no data was sent.',
    );
    assert.equal(result.impact?.egress.dataLeavesOrganisation, null);
  }
});

test(
  'the real HTTP action boundary times out with a bounded useful failure',
  { skip: dbUp ? false : SKIP_MESSAGE },
  async (t) => {
  const server = createServer(() => {
    // Deliberately never respond: execRestConnectorRequest owns the five-second abort boundary.
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise<void>((resolve) => server.close(() => resolve())));
  const address = server.address();
  assert.ok(address && typeof address === 'object');
  const started = Date.now();
  const result = await executeCrmAction(
    { id: 'crm', type: 'rest', endpoint: `http://127.0.0.1:${address.port}` },
    CREATE,
    CONTEXT,
  );
  const elapsed = Date.now() - started;
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.equal(result.code, 'unsupported-connector');
    assert.equal(result.message, 'connector is not a reachable REST source');
  }
  // The LOWER bound is the real signal: the call must actually wait for the five-second abort rather
  // than failing instantly for some unrelated reason, which would make this test pass for the wrong
  // reason. The upper bound only has to prove "bounded, not hanging forever".
  //
  // It used to be `< 7_000`, a wall-clock constant that silently assumed an idle machine. Under a
  // concurrent production build this test took 65s, 118s, then timed out entirely — while passing in
  // 11.3s idle. The abort was firing correctly every time; the event loop was just starved. A gate
  // that fails only when the machine is busy trains people to re-run until green, which is how a real
  // failure eventually gets waved through. A generous ceiling still distinguishes bounded from hung.
  assert.ok(elapsed >= 4_500, `abort fired too early at ${elapsed}ms — the boundary was not exercised`);
  assert.ok(elapsed < 60_000, `not bounded — took ${elapsed}ms, which is a hang rather than a timeout`);
  },
);

import { NextResponse } from 'next/server';
import { writeCrmOpportunityFollowUp } from '@/lib/adapters/crm-writeback';
import { writeCrmTask } from '@/lib/adapters/crm-task-writeback';
import { auditFromSession } from '@/lib/audit-actor';
import { requireAdmin } from '@/lib/authz';
import { listConnectors } from '@/lib/store';
import { currentOrgId } from '@/lib/tenancy';

const STATUS_BY_CODE = {
  'invalid-command': 400,
  'unsupported-connector': 422,
  'record-not-found': 404,
  'idempotency-conflict': 409,
  'upstream-error': 502,
} as const;

// Tenant-scoped CRM action endpoint. The caller chooses only the owned connector id and a typed
// follow-up command; the adapter owns the fixed opportunities path and allowlisted patch.
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const gate = await requireAdmin(req);
  if (gate instanceof NextResponse) return gate;

  const [{ id }, orgId, body] = await Promise.all([
    params,
    currentOrgId(),
    req.json().catch(() => null),
  ]);
  const connector = (await listConnectors(orgId)).find((candidate) => candidate.id === id);
  if (!connector) return NextResponse.json({ error: 'unknown connector' }, { status: 404 });

  const taskOperation = body && typeof body === 'object' && !Array.isArray(body)
    && ((body as Record<string, unknown>).operation === 'create-task'
      || (body as Record<string, unknown>).operation === 'update-task');
  const result = taskOperation
    ? await writeCrmTask(connector, body, orgId)
    : await writeCrmOpportunityFollowUp(connector, body, orgId);
  if (!result.ok) {
    auditFromSession(gate, orgId, {
      action: taskOperation ? 'connector.crm.task.writeback' : 'connector.crm.writeback',
      resource: `connector:${id}`,
      outcome: result.code === 'invalid-command' ? 'blocked' : 'error',
    });
    return NextResponse.json(
      { error: result.message, code: result.code },
      { status: STATUS_BY_CODE[result.code] },
    );
  }

  auditFromSession(gate, orgId, {
    action: taskOperation ? 'connector.crm.task.writeback' : 'connector.crm.writeback',
    resource: taskOperation
      ? `connector:${id}/task:${'taskId' in result.receipt ? result.receipt.taskId : 'unknown'}`
      : `connector:${id}/opportunity:${'opportunityId' in result.receipt ? result.receipt.opportunityId : 'unknown'}`,
    outcome: 'ok',
  });
  return NextResponse.json(result, { status: result.receipt.replayed ? 200 : 201 });
}

import assert from 'node:assert/strict';
import { test } from 'node:test';

import {
  cacheStatusUnconfigured,
  cacheStatusUnreachable,
  computeCacheStats,
  flushAuditResource,
  interpretCachePing,
  normalizeCacheLogs,
  normalizeCachePolicy,
  normalizeCacheType,
  planFlush,
  readCacheHit,
  type RawCacheLog,
  type RawCachePing,
} from '../src/lib/litellm-cache.ts';

// ─── normalizeCacheType ───────────────────────────────────────────────────────────────────────
test('normalizeCacheType: known backends pass, garbage → unknown', () => {
  assert.equal(normalizeCacheType('redis'), 'redis');
  assert.equal(normalizeCacheType('REDIS'), 'redis');
  assert.equal(normalizeCacheType(' local '), 'local');
  assert.equal(normalizeCacheType('s3'), 's3');
  assert.equal(normalizeCacheType('redis-semantic'), 'redis-semantic');
  assert.equal(normalizeCacheType('qdrant-semantic'), 'qdrant-semantic');
  assert.equal(normalizeCacheType('disk'), 'disk');
  assert.equal(normalizeCacheType('memcached'), 'unknown');
  assert.equal(normalizeCacheType(''), 'unknown');
  assert.equal(normalizeCacheType(null), 'unknown');
  assert.equal(normalizeCacheType(42), 'unknown');
});

// ─── normalizeCachePolicy ─────────────────────────────────────────────────────────────────────
test('normalizeCachePolicy: reads echoed params, drops junk', () => {
  const raw: RawCachePing = {
    litellm_cache_params: {
      supported_call_types: ['completion', 'acompletion', '', 42 as unknown as string],
      ttl: 3600,
      mode: 'default_on',
      namespace: 'offgrid',
    },
  };
  const p = normalizeCachePolicy(raw);
  assert.deepEqual(p.supportedCallTypes, ['completion', 'acompletion']);
  assert.equal(p.ttlSeconds, 3600);
  assert.equal(p.mode, 'default_on');
  assert.equal(p.namespace, 'offgrid');
});

test('normalizeCachePolicy: empty policy when no params / negatives dropped', () => {
  assert.deepEqual(normalizeCachePolicy(null), {
    ttlSeconds: null,
    supportedCallTypes: [],
    mode: null,
    namespace: null,
  });
  assert.deepEqual(normalizeCachePolicy({}), {
    ttlSeconds: null,
    supportedCallTypes: [],
    mode: null,
    namespace: null,
  });
  const neg = normalizeCachePolicy({ litellm_cache_params: { ttl: -5, supported_call_types: null } });
  assert.equal(neg.ttlSeconds, null);
  assert.deepEqual(neg.supportedCallTypes, []);
  // whitespace-only mode/namespace → null
  const blank = normalizeCachePolicy({ litellm_cache_params: { mode: '   ', namespace: '' } });
  assert.equal(blank.mode, null);
  assert.equal(blank.namespace, null);
});

// ─── interpretCachePing ───────────────────────────────────────────────────────────────────────
test('interpretCachePing: healthy redis cache → enabled + healthy', () => {
  const s = interpretCachePing({
    status: 'healthy',
    cache_type: 'redis',
    ping_response: true,
    litellm_cache_params: { ttl: 600, supported_call_types: ['completion'] },
  });
  assert.equal(s.configured, true);
  assert.equal(s.reachable, true);
  assert.equal(s.cacheEnabled, true);
  assert.equal(s.healthy, true);
  assert.equal(s.type, 'redis');
  assert.equal(s.policy.ttlSeconds, 600);
});

test('interpretCachePing: ping answered but no cache wired → reachable, not enabled', () => {
  const s = interpretCachePing({ status: 'healthy', cache_type: null });
  assert.equal(s.reachable, true);
  assert.equal(s.cacheEnabled, false);
