// operator MUST supply their own on-prem endpoint URL (the console never guesses where the server
// runs); the pure buildInstallPayload turns entry + endpoint into the EXACT tool-create body, POSTed
// to the EXISTING /api/v1/admin/tools route (type=mcp). No new tool storage — the added tool shows
// up in the builder's ToolPicker "Registered tools" group automatically.
export function McpInstallButton({ server }: Readonly<{ server: McpServer }>) {
  const router = useRouter();
  const pathname = usePathname();
  const params = useSearchParams();
  const open = params.get('install') === server.id;

  const [endpoint, setEndpoint] = useState('');
  const [busy, setBusy] = useState(false);

  const setOpen = useCallback(
    (next: boolean) => {
      const sp = new URLSearchParams(params.toString());
      if (next) sp.set('install', server.id);
      else sp.delete('install');
      const qs = sp.toString();
      router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
    },
    [params, pathname, router, server.id],
  );

  async function add() {
    if (!isInstallable(server, endpoint)) {
      toast.error('Enter the on-prem endpoint where this server runs.');
      return;
    }
    setBusy(true);
    try {
      const res = await fetch('/api/v1/admin/tools', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(buildInstallPayload(server, endpoint)),
      });
      if (!res.ok) throw new Error('failed');
      toast.success(`Added "${server.name}" — now available as a registered MCP tool.`);
      setEndpoint('');
      setOpen(false);
      router.refresh();
    } catch {
      toast.error('Failed to add tool');
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      <Button size="sm" variant="outline" onClick={() => setOpen(true)}>
        <Plus className="size-4" />
        Add
      </Button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent>
          <SheetHeader>
            <SheetTitle>Add {server.name}</SheetTitle>
            <SheetDescription>
              Register this MCP server as a tool your apps can use. It will appear in the
              builder&apos;s tool picker under “Registered tools”.
            </SheetDescription>
          </SheetHeader>
          <SheetBody className="space-y-5">
            <div className="space-y-1.5">
              <Label>1. Run the server on your network</Label>
              <pre className="overflow-x-auto rounded-md border bg-muted/50 px-3 py-2 font-mono text-xs">
                {server.install}
              </pre>
              {server.reachesInternet ? (
                <p className="text-xs text-amber-700">{server.airgapNote}</p>
              ) : (
                <p className="text-xs text-muted-foreground">{server.airgapNote}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="mcp-endpoint">2. Your on-prem endpoint</Label>
              <Input
                id="mcp-endpoint"
                value={endpoint}
                onChange={(e) => setEndpoint(e.target.value)}
                placeholder={server.defaultEndpointHint}
              />
              <p className="text-xs text-muted-foreground">
                Where the server runs on your network — a{' '}
                {server.transport === 'http' ? 'URL' : 'launch command / socket'}. Sample above; the
                console never connects out on its own.
              </p>
            </div>
          </SheetBody>
          <SheetFooter>
            <Button onClick={add} disabled={busy || !endpoint.trim()} className="w-full">
              {busy ? 'Adding…' : `Add ${server.name}`}
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>
    </>
  );
}

import { NextResponse } from 'next/server';
import { requireUser } from '@/lib/authz';
import { type Block, type Catalog, type Workflow, introspect } from '@/lib/studio';

export const dynamic = 'force-dynamic';

import { GATEWAY_URL, gatewayHeaders } from '@/lib/gateway';

// Ask the local gateway to wire a workflow from the available blocks. Falls back to a
// deterministic pipeline if the model is unavailable or returns junk — the canvas always
// gets something coherent.
// eslint-disable-next-line complexity
async function modelPlan(prompt: string, catalog: Catalog, ids: Set<string>): Promise<Workflow | null> {
  const sys =
    'You wire an agentic workflow from a catalog of available building blocks. ' +
    'Each block has an id, a group (Connector|Data|Tool|Guardrail|Model|Agent), and a label. ' +
    'Given the user request, pick the blocks to use and the directed edges between them. ' +
    'Start with one Input (trigger), then Connector/Data sources -> Guardrails -> Tool/Agent -> Model, ' +
    'insert a Human (review) checkpoint before any irreversible Output, and end with an Output (sink). ' +
    'Respond with ONLY minified JSON: {"title":"","summary":"","nodeIds":[],"edges":[{"from":"","to":"","label":""}]}. ' +
    'Use ONLY ids that appear in the catalog.';
  const catalogText = catalog.blocks.map((b) => `${b.id} [${b.group}] ${b.label}`).join('\n');

  try {
    const r = await fetch(`${GATEWAY_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: gatewayHeaders({ 'content-type': 'application/json' }),
      body: JSON.stringify({
        messages: [
          { role: 'system', content: sys },
          { role: 'user', content: `Request: ${prompt}\n\nCatalog:\n${catalogText}` },
        ],
        max_tokens: 700,
        temperature: 0,
        stream: false,
      }),
      signal: AbortSignal.timeout(45000),
    });
    if (r.ok) {
      const data = await r.json();
      const text: string = data?.choices?.[0]?.message?.content ?? '';
      const m = /\{[\s\S]*\}/.exec(text);
      if (m) {
        const wf = JSON.parse(m[0]) as Workflow;
        const nodeIds = (wf.nodeIds ?? []).filter((id) => ids.has(id));
        const edges = (wf.edges ?? []).filter((e) => ids.has(e.from) && ids.has(e.to));
        if (nodeIds.length) return { title: wf.title || 'Workflow', summary: wf.summary || prompt, nodeIds, edges };
      }
    }
  } catch {
    /* model unavailable */
  }
  return null;
}

async function plan(prompt: string, catalog: Catalog): Promise<Workflow> {
  const ids = new Set(catalog.blocks.map((b) => b.id));
  return (await modelPlan(prompt, catalog, ids)) ?? heuristic(prompt, catalog.blocks);
}

function heuristic(prompt: string, blocks: Block[]): Workflow {
  const byGroup = (g: Block['group'], n: number) => blocks.filter((b) => b.group === g).slice(0, n);
  const chain = [
    ...byGroup('Input', 1),
    ...byGroup('Connector', 1),
    ...byGroup('Data', 1),
    ...byGroup('Guardrail', 1),
    ...byGroup('Agent', 1),
    ...byGroup('Human', 1),
    ...byGroup('Output', 1),
  ];
  const edges = chain.slice(0, -1).map((b, i) => ({ from: b.id, to: chain[i + 1].id }));
  return { title: 'Suggested workflow', summary: prompt || 'Wired from available blocks', nodeIds: chain.map((b) => b.id), edges };
}

export async function POST(req: Request) {
  const gate = await requireUser(req);
  if (gate instanceof NextResponse) return gate;
  const { prompt = '' } = await req.json().catch(() => ({ prompt: '' }));
  const catalog = await introspect();
  const workflow = await plan(String(prompt), catalog);
  return NextResponse.json({ catalog, workflow });
}

'use client';

import { Copy, Database, Lightning } from '@phosphor-icons/react/dist/ssr';
import { useCallback, useEffect, useState } from 'react';
import { toast } from 'sonner';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { type DynamicDbCreds, formatTtl } from '@/lib/secrets-ops';

// Dynamic DATABASE secrets. Enumerates the roles configured on the `database` secrets engine and
// generates on-demand, short-lived creds for a role. The minted username/password ARE shown once —
// that is the point of a dynamic secret — with the lease + TTL so the operator knows when it expires.
// If the engine isn't provisioned, the panel says so (stubbed path, per task scope note).
export function DynamicDbPanel({ sealed }: Readonly<{ sealed: boolean }>) {
  const [roles, setRoles] = useState<string[]>([]);
  const [mount, setMount] = useState('database');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<string | null>(null);
  const [creds, setCreds] = useState<{ role: string; creds: DynamicDbCreds } | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/v1/admin/secrets/dynamic-db');
      const d = (await res.json()) as { roles?: string[]; mount?: string };
      setRoles(Array.isArray(d.roles) ? d.roles.filter((r) => !r.endsWith('/')) : []);
      if (d.mount) setMount(d.mount);
    } catch {
      // engine absent / unreachable — treat as no roles
      setRoles([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const generate = async (role: string) => {
    setBusy(role);
    try {
      const res = await fetch('/api/v1/admin/secrets/dynamic-db', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ role }),
      });
      const d = (await res.json()) as { creds?: DynamicDbCreds; error?: string };
      if (!res.ok) throw new Error(d.error ?? 'Failed to generate creds.');
      if (d.creds) setCreds({ role, creds: d.creds });
      toast.success(`Generated dynamic creds for "${role}".`);
    } catch (e) {
      toast.error((e as Error).message);
    } finally {
      setBusy(null);
    }
  };

  const copy = (text: string) => {
    void navigator.clipboard?.writeText(text);
    toast.success('Copied to clipboard.');
  };

  return (
    <Card className="shadow-sm">
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-sm">
          <Database className="size-4 text-muted-foreground" />
          Dynamic database secrets
          <Badge variant="outline" className="font-mono text-[10px] text-muted-foreground">
            {mount}/
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        {loading ? (
          <p className="py-4 text-center text-xs text-muted-foreground">Loading roles…</p>
        ) : roles.length === 0 ? (
          <p className="rounded-md border border-border bg-muted/30 px-3 py-3 text-xs text-muted-foreground">
            The <span className="font-mono">{mount}</span> secrets engine has no roles (or isn&apos;t
            enabled). Enable it and configure a role against a connection to generate on-demand,
            short-lived DB credentials here. Set{' '}
            <span className="font-mono">OFFGRID_OPENBAO_DB_MOUNT</span> if the engine is mounted
            elsewhere.
          </p>
        ) : (
          <div className="space-y-2">
            {roles.map((role) => (
              <div
                key={role}
                className="flex items-center justify-between rounded-md border border-border px-3 py-2"
              >
                <span className="font-mono text-xs text-foreground">{role}</span>
                <Button
                  size="sm"
                  variant="outline"
                  disabled={sealed || busy !== null}
                  onClick={() => void generate(role)}
                >
                  <Lightning className="mr-1 size-3.5" />
                  {busy === role ? 'Generating…' : 'Generate creds'}
                </Button>
              </div>
            ))}
          </div>
        )}

        {creds && (
          <div className="space-y-2 rounded-md border border-primary/40 bg-primary/5 p-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] uppercase tracking-wide text-primary">
                Dynamic creds for {creds.role} — shown once
              </span>
              <span className="text-[10px] text-muted-foreground">
                lease {creds.creds.leaseId ?? '—'} · TTL {formatTtl(creds.creds.leaseDuration)}
              </span>
            </div>
            <CredField label="username" value={creds.creds.username} onCopy={copy} />
            <CredField label="password" value={creds.creds.password} onCopy={copy} />
            <Button size="sm" variant="ghost" onClick={() => setCreds(null)}>
              Dismiss
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function CredField({
  label,
  value,
  onCopy,
}: Readonly<{
  label: string;
  value: string | null;
  onCopy: (text: string) => void;
}>) {
  return (
    <div className="flex items-center gap-2">
      <span className="w-20 text-[10px] uppercase tracking-wide text-muted-foreground">{label}</span>
      <code className="flex-1 truncate rounded bg-background px-2 py-1 font-mono text-xs">
        {value ?? '—'}
      </code>
      {value && (
        <Button size="sm" variant="ghost" onClick={() => onCopy(value)} title={`Copy ${label}`}>
          <Copy className="size-3.5" />
        </Button>
      )}
    </div>
  );
}

import { NextResponse } from 'next/server';
import { requireUser } from '@/lib/authz';

export const dynamic = 'force-dynamic';

// Write-authorizer for the public file store (SeaweedFS behind gateway.getoffgridai.co/files).
// Caddy `forward_auth` calls this ONLY for write methods (PUT/POST/DELETE/PATCH); reads are
// public and never hit it. Returns 200 when the caller presents a valid Keycloak bearer
// (verified via the IdentityVerifier seam in requireUser) or a console session, 401 otherwise.
// It authenticates the same way as every other API surface — no store-specific credentials.
export async function GET(req: Request): Promise<Response> {
  const gate = await requireUser(req);
  return new Response(null, { status: gate instanceof NextResponse ? 401 : 200 });
}

import { auth } from '@/auth';

export const dynamic = 'force-dynamic';

// Session-check endpoint for the edge (Caddy forward_auth). Returns 200 when the
// caller has a valid console session cookie, 401 otherwise — so every public route
// can be gated behind the console's OWN login (no hosted IdP page).
export async function GET(): Promise<Response> {
  const session = await auth();
  return new Response(null, { status: session?.user ? 200 : 401 });
}

import { NextResponse } from 'next/server';
import { auditFromSession } from '@/lib/audit-actor';
import { requireAdmin } from '@/lib/authz';
import { redactBatch, activePiiPort, type RedactionPolicy } from '@/lib/data-redaction';
import { currentOrgId } from '@/lib/tenancy';

export const dynamic = 'force-dynamic';

// Sync-path redaction primitive: given a batch of rows + a column policy, return the redacted rows
// + a report of what was changed. This is what the data-movement path calls BEFORE rows land in
// the warehouse — the same PII engine that governs model access, applied to data in flight.
export async function POST(req: Request) {
  const gate = await requireAdmin(req);
  if (gate instanceof NextResponse) return gate;

  let body: { rows?: unknown; policy?: unknown };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: 'invalid JSON body' }, { status: 400 });
  }
  const rows = Array.isArray(body.rows) ? (body.rows as Record<string, unknown>[]) : null;
  const policy = Array.isArray(body.policy) ? (body.policy as RedactionPolicy) : null;
  if (!rows || !policy) {
    return NextResponse.json({ error: 'rows[] and policy[] are required' }, { status: 400 });
  }

  const orgId = await currentOrgId();
  const pii = await activePiiPort();
  const result = await redactBatch(rows, policy, pii, orgId);

  auditFromSession(gate, orgId, {
    action: 'data.redact',
    resource: `rows:${rows.length} redacted:${result.totalRedacted} cols:${result.report.length}`,
    outcome: 'ok',
  });
  return NextResponse.json(result, { status: 200 });
}
